package com.sledge.browser.desktop

import com.sledge.browser.gate.PermissionGate
import com.sledge.browser.gate.PlatformPermission
import javax.swing.JOptionPane

// Generated by the desktop mirror. The build hook refreshes this file.

/** Desktop has no Android runtime permission. The user answers in a window. */
class DesktopPermissionGate : PermissionGate {
    private val granted = mutableSetOf<PlatformPermission>()

    override fun ask(permission: PlatformPermission, onResult: (Boolean) -> Unit) {
        if (permission in granted) {
            onResult(true)
            return
        }
        val choice = JOptionPane.showConfirmDialog(
            null,
            "Allow this app to use ${permission.label}?",
            "Permission",
            JOptionPane.OK_CANCEL_OPTION,
        )
        val allow = choice == JOptionPane.OK_OPTION
        if (allow) granted += permission
        onResult(allow)
    }
}
